{"source":"def investigate(context, acquire):
    events = context.get('events', [])
    decoder = None
    count = 0
    status = 'open'
    for event in events:
        op = event.get('op')
        if op == 'feed':
            data = bytes(event.get('bytes', []))
            if decoder is None:
                decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            text = decoder.decode(data, False)
            if text is None:
                status = 'error'
            else:
                count += len(text)
        elif op == 'finish':
            if decoder is None:
                decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            text = decoder.decode(b'', True)
            if text is None:
                status = 'error'
            else:
                count += len(text)
                status = 'finished'
        elif op == 'reset':
            decoder = __import__('codecs').getincrementaldecoder('utf-8')()
            count = 0
            status = 'open'
    return {'count': count, 'status': status}
","scope":"Native strict UTF-8 incremental decoder: create the decoder lazily on first feed/finish, retain state across feeds, count code points only from successful decode calls, mark error on malformed input, finish only when the buffered prefix is complete, and reset count/status/decoder on reset.","change":"Removed the unsupported try/except error handling and the decoder=None defect. Feed and finish now lazily construct the strict UTF-8 incremental decoder; a failed decode is represented by a None result, which sets status to error and contributes zero characters, while successful text is counted and finish sets finished."}
